schemas.schema-01-systematic.prisma:
/// System configuration key-value storage for the Todo List application.
///
/// Stores system-wide parameters and settings that control application
/// behavior and feature toggles. Each configuration entry contains a unique
/// key name, associated string value, human-readable description, and
/// lifecycle timestamps. This facilitates dynamic configuration without
/// requiring code changes or system redeployment.
///
/// Configurations are managed independently and may be updated by
/// administrators or system processes. The table supports soft deletion to
/// preserve audit trails and enable recovery if necessary.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_system_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique configuration key identifier used for lookup and management.
  key String

  /// Configuration value stored as string, typically representing a setting or
  /// parameter value.
  value String

  /// Human-readable explanation of the configuration entry and its purpose.
  description String?

  /// Timestamp when the configuration entry was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the configuration entry was last modified.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp indicating when the entry was marked deleted, if
  /// applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([created_at, updated_at])
}

schemas.schema-02-actors.prisma:
/// Guests who visit the Todo List application without registration.
///
/// This table stores basic guest visitor information for tracking anonymous
/// sessions and limited interaction capabilities.
/// Guests represent unregistered users visiting the platform with no
/// authentication requirements.
///
/// Each guest has a unique UUID primary key and temporal fields for creation
/// and updates.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// IP address of the guest visitor for tracking purposes.
  visitor_ip String

  /// Timestamp when the guest record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest record was last updated.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_list_guest_sessions todo_list_guest_sessions[]

  @@index([visitor_ip, created_at])
}

/// Session records for guest visitors of the Todo List application.
///
/// Tracks anonymous sessions for guests, including connection context and
/// session lifecycle details.
///
/// Each session belongs to exactly one guest, enabling session-based
/// interaction tracking without authentication.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_guest_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the guest who owns this session. {@link todo_list_guests.id}.
  todo_list_guest_id String @db.Uuid

  /// IP address of the session connection.
  ip String

  /// Connection URL for the session.
  href String

  /// Referrer URL for the session.
  referrer String

  /// Session creation time.
  created_at DateTime @db.Timestamptz

  /// Session expiration time, null if session is currently active.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  guest todo_list_guests @relation(fields: [todo_list_guest_id], references: [id], onDelete: Cascade)

  @@index([todo_list_guest_id, created_at])
}

/// Registered users who can create, read, update, and delete their own todo
/// items.
///
/// This table stores user authentication credentials, including secure
/// password hashes and contact emails.
///
/// Each user record contains a unique UUID primary key along with timestamps
/// for auditing purposes.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User email address used for authentication and communication.
  email String

  /// Hashed password for secure user authentication.
  password_hash String

  /// Timestamp when the user was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the user was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the user was soft deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_list_user_sessions todo_list_user_sessions[]
  todo_list_todos todo_list_todos[]

  @@unique([email])
}

/// Session records for registered users of the Todo List application.
///
/// Tracks authenticated user sessions with security and connection details.
///
/// Each session belongs to exactly one user and records creation and
/// expiration times for session lifecycle management.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the user who owns this session. {@link todo_list_users.id}.
  todo_list_user_id String @db.Uuid

  /// IP address of the session connection.
  ip String

  /// Connection URL for the session.
  href String

  /// Referrer URL for the session.
  referrer String

  /// Session creation time.
  created_at DateTime @db.Timestamptz

  /// Session expiration time, null if session is currently active.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_list_users @relation(fields: [todo_list_user_id], references: [id], onDelete: Cascade)

  @@index([todo_list_user_id, created_at])
}

/// Administrators of the Todo List application with full system privileges.
///
/// This table stores admin authentication data including email and hashed
/// password.
///
/// Admins have a unique UUID primary key and timestamps for auditing their
/// account lifecycle.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Admin email address for authentication and communication.
  email String

  /// Hashed password for secure admin authentication.
  password_hash String

  /// Timestamp when the admin account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the admin account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the admin account was soft deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_list_admin_sessions todo_list_admin_sessions[]

  @@unique([email])
}

/// Session records for administrators of the Todo List application.
///
/// Tracks admin user sessions including connection information and session
/// lifetimes.
///
/// Each session links to one admin and records creation and expiration times
/// for session management.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_admin_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the admin who owns this session. {@link todo_list_admins.id}.
  todo_list_admin_id String @db.Uuid

  /// IP address of the session connection.
  ip String

  /// Connection URL for the session.
  href String

  /// Referrer URL for the session.
  referrer String

  /// Session creation time.
  created_at DateTime @db.Timestamptz

  /// Session expiration time, null if session is currently active.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin todo_list_admins @relation(fields: [todo_list_admin_id], references: [id], onDelete: Cascade)

  @@index([todo_list_admin_id, created_at])
}

schemas.schema-03-todos.prisma:
/// Todo list items representing individual tasks managed by registered users.
///
/// Each todo item is uniquely identified and owned by a user. The model
/// supports task metadata including title, optional description, completion
/// status, and standard timestamps for creation, updates, and soft deletion.
///
/// Ownership is enforced via a foreign key to the todo_list_users table
/// ensuring that users can only manage their own todo items.
///
/// Soft deletion is implemented to allow reversible deletion while
/// preserving historical audit trails.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_list_todos {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner user of the todo item. {@link todo_list_users.id}.
  todo_list_user_id String @db.Uuid

  /// Title of the todo item, required and limited to a reasonable length for
  /// usability.
  title String

  /// Optional detailed description of the todo item providing additional
  /// context and information.
  description String?

  /// Flag indicating whether the todo item is marked as completed.
  is_complete Boolean

  /// Timestamp when the todo item was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the todo item was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp indicating soft deletion status; null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_list_users @relation(fields: [todo_list_user_id], references: [id], onDelete: Cascade)

  @@index([todo_list_user_id])
}

