import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodoListUser";
import type { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";

export async function test_api_todo_list_user_session_update_by_owner(
  connection: api.IConnection,
) {
  // 1. User joins (registers) to create an authenticated user
  const userCreateBody = {
    email: `${RandomGenerator.name(1).toLowerCase()}${RandomGenerator.alphaNumeric(3)}@example.com`,
    name: RandomGenerator.name(),
  } satisfies ITodoListTodoListUser.ICreate;
  const authorizedUser: ITodoListTodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: userCreateBody,
    });
  typia.assert(authorizedUser);

  // 2. Create a new user session for this user
  const sessionCreateBody = {
    ip: `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.
${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.
${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.
${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}`,
    href: `https://${RandomGenerator.name(1)}.example.com/path`,
    referrer: `https://referrer.example.com/${RandomGenerator.alphaNumeric(5)}`,
    expired_at: null,
  } satisfies ITodoListUserSession.ICreate;
  const session: ITodoListUserSession =
    await api.functional.todoList.user.todoListUsers.todoListUserSessions.create(
      connection,
      {
        todoListUserId: authorizedUser.id,
        body: sessionCreateBody,
      },
    );
  typia.assert(session);

  // 3. Update session connection metadata
  const updatedSessionBody = {
    ip: `${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.
${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.
${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}.
${typia.random<number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>>()}`,
    href: `https://updated.${RandomGenerator.name(1)}.example.com/updatedpath`,
    referrer: `https://updates_referrer.example.com/${RandomGenerator.alphaNumeric(7)}`,
    expired_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
  } satisfies ITodoListUserSession.IUpdate;

  const updatedSession: ITodoListUserSession =
    await api.functional.todoList.user.todoListUsers.todoListUserSessions.update(
      connection,
      {
        todoListUserId: authorizedUser.id,
        id: session.id,
        body: updatedSessionBody,
      },
    );
  typia.assert(updatedSession);

  // 4. Confirm the updated fields match what was sent
  TestValidator.equals(
    "IP address should be updated",
    updatedSession.ip,
    updatedSessionBody.ip,
  );
  TestValidator.equals(
    "Href should be updated",
    updatedSession.href,
    updatedSessionBody.href,
  );
  TestValidator.equals(
    "Referrer should be updated",
    updatedSession.referrer,
    updatedSessionBody.referrer,
  );
  TestValidator.equals(
    "Expired_at should be updated",
    updatedSession.expired_at,
    updatedSessionBody.expired_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuest";
import type { ITodoListGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuestSession";
import type { ITodoListTodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodoListUser";

export async function test_api_todo_list_guest_session_retrieval_by_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Authenticate user with POST /auth/user/join
  const userAuth: ITodoListTodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: {
        email: RandomGenerator.alphaNumeric(6) + "@example.com",
        name: RandomGenerator.name(),
      } satisfies ITodoListTodoListUser.ICreate,
    });
  typia.assert(userAuth);

  // 2. Create a todoListGuest with POST /todoList/todoListGuests
  const guestCreateBody = {
    visitor_ip: [
      RandomGenerator.pick(["123", "192", "10", "172"] as const),
      ".",
      RandomGenerator.pick(["0", "168", "16", "254"] as const),
      ".",
      RandomGenerator.pick(["0", "1", "255"] as const),
      ".",
      String(Math.floor(Math.random() * 255)),
    ].join(""),
  } satisfies ITodoListGuest.ICreate;

  const guest: ITodoListGuest =
    await api.functional.todoList.todoListGuests.create(connection, {
      body: guestCreateBody,
    });
  typia.assert(guest);

  // 3. Create a todoListGuestSession with POST /todoList/user/todoListGuests/{todoListGuestId}/todoListGuestSessions
  const sessionCreateBody = {
    ip: guest.visitor_ip,
    href: "https://example.com/todolist",
    referrer: "https://referrer.com/page",
    created_at: new Date().toISOString(),
    expired_at: null,
  } satisfies ITodoListGuestSession.ICreate;

  const session: ITodoListGuestSession =
    await api.functional.todoList.user.todoListGuests.todoListGuestSessions.create(
      connection,
      {
        todoListGuestId: guest.id,
        body: sessionCreateBody,
      },
    );
  typia.assert(session);

  // 4. Retrieve the todoListGuestSession by GET /todoList/user/todoListGuests/{todoListGuestId}/todoListGuestSessions/{id}
  const retrieved: ITodoListGuestSession =
    await api.functional.todoList.user.todoListGuests.todoListGuestSessions.at(
      connection,
      {
        todoListGuestId: guest.id,
        id: session.id,
      },
    );
  typia.assert(retrieved);

  // Validate that the retrieved session matches the created session
  TestValidator.equals(
    "todoListGuestSession.id matches",
    retrieved.id,
    session.id,
  );
  TestValidator.equals(
    "todoListGuestSession.todoListGuestId matches",
    retrieved.todo_list_guest_id,
    guest.id,
  );
  TestValidator.equals(
    "todoListGuestSession.ip matches",
    retrieved.ip,
    sessionCreateBody.ip,
  );
  TestValidator.equals(
    "todoListGuestSession.href matches",
    retrieved.href,
    sessionCreateBody.href,
  );
  TestValidator.equals(
    "todoListGuestSession.referrer matches",
    retrieved.referrer,
    sessionCreateBody.referrer,
  );
  TestValidator.equals(
    "todoListGuestSession.created_at matches",
    retrieved.created_at,
    sessionCreateBody.created_at,
  );
  TestValidator.equals(
    "todoListGuestSession.expired_at matches",
    retrieved.expired_at,
    sessionCreateBody.expired_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuest";
import type { ITodoListGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuestSession";
import type { ITodoListTodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodoListUser";

export async function test_api_todo_list_guest_session_creation_by_authenticated_user(
  connection: api.IConnection,
) {
  // 1. Create a new user account via /auth/user/join to authenticate and obtain a token
  const userCreateBody = {
    email: `user_${RandomGenerator.alphaNumeric(6)}@example.com`,
    name: RandomGenerator.name(),
  } satisfies ITodoListTodoListUser.ICreate;

  const authorizedUser: ITodoListTodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, { body: userCreateBody });
  typia.assert(authorizedUser);

  // 2. Create a new todo list guest via /todoList/todoListGuests
  const guestCreateBody = {
    visitor_ip: "203.0.113." + RandomGenerator.alphaNumeric(3),
  } satisfies ITodoListGuest.ICreate;

  const guest: ITodoListGuest =
    await api.functional.todoList.todoListGuests.create(connection, {
      body: guestCreateBody,
    });
  typia.assert(guest);

  TestValidator.predicate(
    "guest visitor_ip is non-empty string",
    typeof guest.visitor_ip === "string" && guest.visitor_ip.length > 0,
  );

  // 3. Create a todo list guest session associated with the created guest
  const nowISOString = new Date().toISOString();
  const guestSessionCreateBody = {
    ip: guestCreateBody.visitor_ip,
    href: `https://example.com/todo?guest=${guest.id}`,
    referrer: "https://google.com/search?q=todo+list+app",
    created_at: nowISOString,
    expired_at: null,
  } satisfies ITodoListGuestSession.ICreate;

  const guestSession: ITodoListGuestSession =
    await api.functional.todoList.user.todoListGuests.todoListGuestSessions.create(
      connection,
      {
        todoListGuestId: guest.id,
        body: guestSessionCreateBody,
      },
    );
  typia.assert(guestSession);

  // Validate that session is associated correctly with the guest
  TestValidator.equals(
    "guest session todo_list_guest_id matches guest id",
    guestSession.todo_list_guest_id,
    guest.id,
  );

  // Validate that IP address matches what was set
  TestValidator.equals(
    "guest session IP matches visitor_ip",
    guestSession.ip,
    guestCreateBody.visitor_ip,
  );

  // Validate href, referrer and timestamps for correctness and format
  TestValidator.equals(
    "guest session href is correct",
    guestSession.href,
    guestSessionCreateBody.href,
  );

  TestValidator.equals(
    "guest session referrer is correct",
    guestSession.referrer,
    guestSessionCreateBody.referrer,
  );

  TestValidator.equals(
    "guest session created_at matches",
    guestSession.created_at,
    guestSessionCreateBody.created_at,
  );

  TestValidator.equals(
    "guest session expired_at is null",
    guestSession.expired_at,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuest";

export async function test_api_todo_list_guest_creation_public(
  connection: api.IConnection,
) {
  // Generate a realistic IPv4 address string
  const visitorIp = `${RandomGenerator.pick([..."0123456789"])}${RandomGenerator.pick([..."0123456789"])}.${RandomGenerator.pick([..."0123456789"])}${RandomGenerator.pick([..."0123456789"])}.${RandomGenerator.pick([..."0123456789"])}${RandomGenerator.pick([..."0123456789"])}.${RandomGenerator.pick([..."0123456789"])}${RandomGenerator.pick([..."0123456789"])}`;

  // Create a new todo list guest using the API
  const guest: ITodoListGuest =
    await api.functional.todoList.todoListGuests.create(connection, {
      body: {
        visitor_ip: visitorIp,
      } satisfies ITodoListGuest.ICreate,
    });

  // Assert that the response matches the expected ITodoListGuest structure
  typia.assert(guest);

  // Verify that the visitor IP matches the input
  TestValidator.equals(
    "guest visitor_ip matches input",
    guest.visitor_ip,
    visitorIp,
  );

  // Verify ID is a valid UUID
  TestValidator.predicate(
    "guest id is valid uuid",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      guest.id,
    ),
  );

  // Verify created_at and updated_at are valid ISO datetime strings
  TestValidator.predicate(
    "guest created_at is valid date-time",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?Z$/.test(
      guest.created_at,
    ),
  );

  TestValidator.predicate(
    "guest updated_at is valid date-time",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]+)?Z$/.test(
      guest.updated_at,
    ),
  );
}

