  typia.assert(updatedTodo);

  // 4. Validate that the update reflected the changes
  TestValidator.equals(
    "todo id remains same after update",
    updatedTodo.id,
    todo.id,
  );
  TestValidator.equals("title updated correctly", updatedTodo.title, newTitle);
  TestValidator.equals(
    "description updated correctly",
    updatedTodo.description,
    newDescription,
  );
  TestValidator.equals(
    "isComplete updated correctly",
    updatedTodo.isComplete,
    newIsComplete,
  );

  // 5. Validate that updatedAt is updated and after createdAt
  TestValidator.predicate(
    "updatedAt is a later date than createdAt",
    new Date(updatedTodo.updatedAt) > new Date(updatedTodo.createdAt),
  );

  // Note: No soft-delete or non-existent todo update tests here as no explicit delete or get API provided
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuest";
import type { ITodoListGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuestSession";
import type { ITodoListTodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodoListUser";

export async function test_api_todo_list_guest_session_update_by_user(
  connection: api.IConnection,
) {
  // Step 1: User registration for authorization
  const userCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    name: RandomGenerator.name(),
  } satisfies ITodoListTodoListUser.ICreate;

  const user: ITodoListTodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: userCreate,
    });
  typia.assert(user);

  // Step 2: Create a Guest user
  const guestCreate = {
    visitor_ip: RandomGenerator.pick([
      "192.168.1.100",
      "10.0.0.110",
      "172.16.0.5",
    ] as const),
  } satisfies ITodoListGuest.ICreate;

  const guest: ITodoListGuest =
    await api.functional.todoList.todoListGuests.create(connection, {
      body: guestCreate,
    });
  typia.assert(guest);

  // Step 3: Create a Guest Session for the guest
  const sessionCreate = {
    ip: guest.visitor_ip,
    href: `https://example.com/page/${RandomGenerator.alphabets(5)}`,
    referrer: `https://referrer.com/page/${RandomGenerator.alphabets(5)}`,
    created_at: new Date().toISOString(),
    expired_at: null,
  } satisfies ITodoListGuestSession.ICreate;

  const guestSession: ITodoListGuestSession =
    await api.functional.todoList.user.todoListGuests.todoListGuestSessions.create(
      connection,
      {
        todoListGuestId: guest.id,
        body: sessionCreate,
      },
    );
  typia.assert(guestSession);

  // Step 4: Update the Guest Session with new information
  const updatedIp = RandomGenerator.pick([
    "192.168.10.200",
    "10.1.1.11",
    "172.16.50.25",
  ] as const);
  const updatedHref = `https://updated.com/page/${RandomGenerator.alphabets(5)}`;
  const updatedReferrer = `https://updatedreferrer.com/page/${RandomGenerator.alphabets(5)}`;
  const updatedCreatedAt = new Date(Date.now() - 60 * 60 * 1000).toISOString(); // 1 hour ago
  const updatedExpiredAt = new Date(
    Date.now() + 24 * 60 * 60 * 1000,
  ).toISOString(); // +1 day

  const sessionUpdate = {
    ip: updatedIp,
    href: updatedHref,
    referrer: updatedReferrer,
    created_at: updatedCreatedAt,
    expired_at: updatedExpiredAt,
  } satisfies ITodoListGuestSession.IUpdate;

  const updatedGuestSession: ITodoListGuestSession =
    await api.functional.todoList.user.todoListGuests.todoListGuestSessions.update(
      connection,
      {
        todoListGuestId: guest.id,
        id: guestSession.id,
        body: sessionUpdate,
      },
    );
  typia.assert(updatedGuestSession);

  // Step 5: Validate that the updated session matches the update request
  TestValidator.equals(
    "Updated IP address should match",
    updatedGuestSession.ip,
    updatedIp,
  );
  TestValidator.equals(
    "Updated href should match",
    updatedGuestSession.href,
    updatedHref,
  );
  TestValidator.equals(
    "Updated referrer should match",
    updatedGuestSession.referrer,
    updatedReferrer,
  );
  TestValidator.equals(
    "Updated created_at should match",
    updatedGuestSession.created_at,
    updatedCreatedAt,
  );
  TestValidator.equals(
    "Updated expired_at should match",
    updatedGuestSession.expired_at,
    updatedExpiredAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuest";
import type { ITodoListGuestSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListGuestSession";
import type { ITodoListTodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodoListUser";

/**
 * End to end test function to validate deletion of a guest session by a
 * registered user.
 *
 * This test performs user join to authenticate, then creates a guest, creates a
 * guest session, and deletes the session via the API. It finally attempts to
 * delete the same session to verify removal.
 */
export async function test_api_todo_list_guest_session_deletion_by_user(
  connection: api.IConnection,
) {
  // 1. Authenticate as a new user
  const userBody = {
    email: RandomGenerator.alphaNumeric(8) + "@example.com",
    name: RandomGenerator.name(),
  } satisfies ITodoListTodoListUser.ICreate;
  const authorizedUser: ITodoListTodoListUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: userBody,
    });
  typia.assert(authorizedUser);

  // 2. Create a guest user
  const guestBody = {
    visitor_ip: "192.168." + RandomGenerator.alphaNumeric(3),
  } satisfies ITodoListGuest.ICreate;
  const guest: ITodoListGuest =
    await api.functional.todoList.todoListGuests.create(connection, {
      body: guestBody,
    });
  typia.assert(guest);

  // 3. Create a guest session
  const nowIsoString: string = new Date().toISOString();
  const sessionBody = {
    ip: guest.visitor_ip,
    href: "https://example.com/dashboard",
    referrer: "https://google.com",
    created_at: nowIsoString,
    expired_at: null,
  } satisfies ITodoListGuestSession.ICreate;

  const session: ITodoListGuestSession =
    await api.functional.todoList.user.todoListGuests.todoListGuestSessions.create(
      connection,
      {
        todoListGuestId: guest.id,
        body: sessionBody,
      },
    );
  typia.assert(session);

  // 4. Delete the guest session
  await api.functional.todoList.user.todoListGuests.todoListGuestSessions.erase(
    connection,
    {
      todoListGuestId: guest.id,
      id: session.id,
    },
  );

  // 5. Verify deletion by expecting error on repeated delete
  await TestValidator.error(
    "Deleting non-existent session should fail",
    async () => {
      await api.functional.todoList.user.todoListGuests.todoListGuestSessions.erase(
        connection,
        {
          todoListGuestId: guest.id,
          id: session.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListAdmin";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";

/**
 * Validate the retrieval of filtered and paginated list of Todo List
 * administrators.
 *
 * This test verifies admin authentication via join operation, then performs
 * multiple queries to the /todoList/admin/todoListAdmins endpoint with various
 * filter parameters including email substring, status, and creation/update date
 * ranges.
 *
 * Steps:
 *
 * 1. Authenticate as admin using join operation to gain necessary authorization.
 * 2. Query the todo list administrators without filters to test pagination
 *    defaults.
 * 3. Query the list filtered by partial email matching.
 * 4. Query the list filtered by status.
 * 5. Query the list filtered by creation and update date ranges.
 * 6. Validate response data types and properties with typia.assert.
 * 7. Validate pagination information is consistent and logical.
 * 8. Confirm filtering results are consistent with parameters.
 */
export async function test_api_todo_list_admin_list_with_authentication(
  connection: api.IConnection,
) {
  // 1. Admin joins (authentication)
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "secretpassword";
  const createBody = {
    email: adminEmail,
    password: adminPassword,
  } satisfies ITodoListAdmin.ICreate;

  const admin: ITodoListAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: createBody });
  typia.assert(admin);
  TestValidator.predicate(
    "admin token exists",
    typeof admin.token.access === "string" && admin.token.access.length > 0,
  );

  // 2. Query list with no filters (pagination defaults)
  const emptyFilter: ITodoListAdmin.IRequest = {};
  const pageDefault: IPageITodoListAdmin.ISummary =
    await api.functional.todoList.admin.todoListAdmins.index(connection, {
      body: emptyFilter,
    });
  typia.assert(pageDefault);
  TestValidator.predicate(
    "pagination current page equal or greater than 1",
    pageDefault.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit positive",
    pageDefault.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination pages >= 1",
    pageDefault.pagination.pages >= 1,
  );
  TestValidator.predicate(
    "pagination records >= 0",
    pageDefault.pagination.records >= 0,
  );
  TestValidator.predicate(
    "returned data count less or equal limit",
    pageDefault.data.length <= pageDefault.pagination.limit,
  );

  // 3. Query filtering by partial email substring
  // Extract a part of adminEmail to filter
  const emailFilter = adminEmail.substring(1, Math.min(7, adminEmail.length));
  const emailFilterBody: ITodoListAdmin.IRequest = {
    search_email: emailFilter,
  };
  const pageFilteredByEmail: IPageITodoListAdmin.ISummary =
    await api.functional.todoList.admin.todoListAdmins.index(connection, {
      body: emailFilterBody,
    });
  typia.assert(pageFilteredByEmail);
  for (const adminSummary of pageFilteredByEmail.data) {
    TestValidator.predicate(
      `admin email contains filter substring: ${emailFilter}`,
      adminSummary.email.includes(emailFilter),
    );
  }

  // 4. Query filtering by status (assuming statuses like 'active')
  // Since schema does not specify allowed status values, use "active" reliably
  const statusFilter: ITodoListAdmin.IRequest = { status: "active" };
  const pageFilteredByStatus: IPageITodoListAdmin.ISummary =
    await api.functional.todoList.admin.todoListAdmins.index(connection, {
      body: statusFilter,
    });
  typia.assert(pageFilteredByStatus);
  // We have no schema property to check status on summaries; must skip direct validation

  // 5. Query filtering by creation and update date range
  // Use ISO strings with realistic range
  const now = new Date();
  const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const dateRangeFilter: ITodoListAdmin.IRequest = {
    created_at_from: weekAgo.toISOString(),
    created_at_to: now.toISOString(),
    updated_at_from: weekAgo.toISOString(),
    updated_at_to: now.toISOString(),
  };
  const pageFilteredByDate: IPageITodoListAdmin.ISummary =
    await api.functional.todoList.admin.todoListAdmins.index(connection, {
      body: dateRangeFilter,
    });
  typia.assert(pageFilteredByDate);
  for (const adminSummary of pageFilteredByDate.data) {
    const createdAt = new Date(adminSummary.created_at);
    const updatedAt = new Date(adminSummary.updated_at);
    TestValidator.predicate(
      `created_at within range ${dateRangeFilter.created_at_from} - ${dateRangeFilter.created_at_to}`,
      createdAt >= weekAgo && createdAt <= now,
    );
    TestValidator.predicate(
      `updated_at within range ${dateRangeFilter.updated_at_from} - ${dateRangeFilter.updated_at_to}`,
      updatedAt >= weekAgo && updatedAt <= now,
    );
  }
}

